def create_effective_prompt(goal, context=None, format=None, examples=None):
    prompt = f"""Goal: {goal}
    """

    if context:
        prompt += f"Context: {context}
    """

    if format:
        prompt += f"Format: {format}
    """

    if examples:
        prompt += f"Examples: {examples}
    """

    return prompt
